const now = new Date().toISOString();
console.log(`🔄 Call Center Multi-Agent Analysis started at ${now}`);
return [{
  json: {
    timestamp: now,
    message: "Cron job started - checking for unprocessed calls"
  }
}];

const callData = $input.first().json;
let s3Key = '';
if (callData.call_direction) {
  s3Key = `calls/${callData.call_direction.toLowerCase()}/${callData.callid}.wav`;
} else if (callData.s3_path) {
  s3Key = callData.s3_path.replace('s3://callintech/', '');
} else if (callData.file_url) {
  if (callData.file_url.toLowerCase().includes("inbound")) {
    s3Key = `calls/inbound/${callData.callid}.wav`;
  } else if (callData.file_url.toLowerCase().includes("outbound")) {
    s3Key = `calls/outbound/${callData.callid}.wav`;
  } else {
    s3Key = `calls/inbound/${callData.callid}.wav`;
  }
}
console.log('Processing call:', callData.callid, 'S3 Key:', s3Key);
return [{
  json: {
    ...callData,
    Key: s3Key
  }
}];

const inputItem = $input.first().json;
let words = [];
let sttError = null;
let callid = 'unknown';
if (inputItem.error) {
  sttError = inputItem.error.message || 'ElevenLabs STT error';
} else {
  try {
    words = inputItem.words || [];
    callid = $('Prepare S3 Download').item.json.callid || 'unknown';
    if (!words.length) sttError = 'No words in transcription';
  } catch (e) {
    sttError = 'Parse error: ' + e.message;
  }
}
if (sttError) {
  return [{ json: { callid, conversation: [], error: sttError } }];
}
const sortedWords = words.sort((a, b) => a.start - b.start);
const conversation = [];
let currentSpeaker = null;
let currentText = '';
let currentStart = null;
let currentEnd = null;
let index = 0;
for (const word of sortedWords) {
  const speaker = word.speaker_id ? `speaker_${word.speaker_id}` : 'unknown';
  if (speaker !== currentSpeaker) {
    if (currentSpeaker !== null && currentText.trim()) {
      conversation.push({ speaker: currentSpeaker, text: currentText.trim(), start: currentStart, end: currentEnd, conversation_index: index++ });
    }
    currentSpeaker = speaker;
    currentText = word.text || '';
    currentStart = word.start;
    currentEnd = word.end;
  } else {
    currentText += ' ' + (word.text || '');
    currentEnd = word.end;
  }
}
if (currentSpeaker !== null && currentText.trim()) {
  conversation.push({ speaker: currentSpeaker, text: currentText.trim(), start: currentStart, end: currentEnd, conversation_index: index++ });
}
return [{ json: { callid, conversation, error: null } }];

const item = $input.first().json;
const callid = item.callid || 'unknown';
const errorMsg = item.error || 'Unknown STT/Conv error';
console.log(`Error processing call ${callid}: ${errorMsg}`);
return [{
  json: {
    callid,
    success: true,
    error: errorMsg,
    processed: true
  }
}];

const conversation = $input.item.json.conversations || [];
const callid = $input.item.json.callid || 'unknown';
const germanWords = ['Hallo', 'Danke', 'bitte', 'ja', 'nein', 'ist', 'das', 'und', 'ich', 'Sie'];
let germanCount = 0;
let totalWords = 0;
conversation.forEach(turn => {
  if (turn.text) {
    const words = turn.text.split(/\s+/);
    totalWords += words.length;
    words.forEach(word => {
      if (germanWords.includes(word.toLowerCase().replace(/[.,!?]/g, ''))) germanCount++;
    });
  }
});
const detectedLanguage = (totalWords > 0 && (germanCount / totalWords) > 0.05) ? 'de' : 'en';
console.log(`Language detected: ${detectedLanguage} (German: ${germanCount}/${totalWords})`);
return {
  json: {
    callid,
    conversation,
    detected_language: detectedLanguage
  }
};

const input = $input.first().json;
const conversation = input.conversation || [];
const callid = input.callid || 'unknown';
const language = input.detected_language || 'en';
const agents = [
  { agent_id: 1, agent_type: 'conversation_structure', agent_name: 'Conversation Structure Analyzer', callid, conversation, language, focus_areas: ['speaker_identification', 'conversation_flow', 'structure_quality'] },
  { agent_id: 2, agent_type: 'sentiment_analysis', agent_name: 'Sentiment & Emotion Analyzer', callid, conversation, language, focus_areas: ['sentiment', 'emotion', 'tone'] },
  { agent_id: 3, agent_type: 'content_analysis', agent_name: 'Content & Topic Analyzer', callid, conversation, language, focus_areas: ['topic', 'keywords', 'service_mentions'] },
  { agent_id: 4, agent_type: 'sales_analysis', agent_name: 'Sales Process Analyzer', callid, conversation, language, focus_areas: ['sales_outcome', 'negotiation', 'commitment'] },
  { agent_id: 5, agent_type: 'service_quality', agent_name: 'Service Quality Analyzer', callid, conversation, language, focus_areas: ['politeness', 'professionalism', 'customer_experience'] }
];
return agents.map(a => ({ json: a }));

const agentData = $json;
const type = agentData.agent_type;
const lang = agentData.language || 'en';
const conv = agentData.conversation || [];
const convJson = JSON.stringify(conv, null, 2);
let sysPrompt = '';
let userPrompt = '';
let modelInfo = {};
if (type === 'conversation_structure') {
  sysPrompt = 'You are a conversation structure expert.';
  userPrompt = `Analyze structure:\n${convJson}\n\nReturn JSON: agent, conversation_flow_quality, dialogue_coherence, any_structural_issues`;
  modelInfo = { model: 'claude-3-opus-20240229', temp: 0.2 };
} else if (type === 'sentiment_analysis') {
  sysPrompt = 'You are a sentiment analysis expert.';
  userPrompt = `Analyze sentiment:\n${convJson}\n\nReturn JSON: sentiment, customer_emotions, satisfaction_level`;
  modelInfo = { model: 'gemini-2.5-flash-preview-05-20', temp: 0.3 };
} else if (type === 'content_analysis') {
  sysPrompt = 'You are a content analysis expert.';
  userPrompt = `Analyze content:\n${convJson}\n\nReturn JSON: topic, keywords, action_items`;
  modelInfo = { model: 'gpt-4.1-2025-04-14', temp: 0.3 };
} else if (type === 'sales_analysis') {
  sysPrompt = 'You are a sales process expert.';
  userPrompt = `Analyze sales:\n${convJson}\n\nReturn JSON: sales_outcome, customer_commitment, sale_value_scale`;
  modelInfo = { model: 'gpt-4o-mini', temp: 0.2 };
} else if (type === 'service_quality') {
  sysPrompt = 'You are a service quality expert.';
  userPrompt = `Analyze quality:\n${convJson}\n\nReturn JSON: agent_politeness, customer_experience`;
  modelInfo = { model: 'claude-3-opus-20240229', temp: 0.2 };
}
return { json: { ...agentData, system_prompt: sysPrompt, user_prompt: userPrompt, model_config: modelInfo } };

const input = $input.first().json;
const type = input.agent_type || 'unknown';
let text = input.text || '{}';
if (text.includes('```json')) text = text.split('```json')[1].split('```')[0].trim();
else if (text.includes('```')) text = text.split('```')[1].split('```')[0].trim();
let result = {};
try {
  result = JSON.parse(text);
  result.agent_type = type;
  result.callid = input.callid;
} catch (e) {
  result = { agent_type: type, callid: input.callid, error: e.message, raw_response: input.text };
}
return { json: result };

