const allItems = $input.all();
const callid = allItems[0]?.json?.callid || 'unknown';
let combinedOutput = { callid };
allItems.forEach(item => {
  const type = item.json.agent_type;
  if (type === 'conversation_structure') {
    combinedOutput.agent = item.json.agent;
    combinedOutput.speaker_identification = item.json.speaker_identification;
  }
  if (type === 'sentiment_analysis') {
    combinedOutput.sentiment = item.json.sentiment;
    combinedOutput.customer_emotions = item.json.customer_emotions;
  }
  if (type === 'content_analysis') {
    combinedOutput.topic = item.json.topic;
    combinedOutput.significant_term = item.json.keywords?.[0];
    combinedOutput.action_items = item.json.action_items;
  }
  if (type === 'sales_analysis') {
    combinedOutput.sale_outcome = item.json.sales_outcome;
    combinedOutput.sale_value_scale = item.json.sale_value_scale;
    combinedOutput.customer_commitment = item.json.customer_commitment;
  }
  if (type === 'service_quality') {
    combinedOutput.agent_politeness = item.json.agent_politeness;
    combinedOutput.customer_experience = item.json.customer_experience;
  }
});
combinedOutput.general_value = combinedOutput.customer_commitment;
combinedOutput.general_experience = combinedOutput.customer_experience;
combinedOutput.text = JSON.stringify(combinedOutput, null, 2);
console.log('Combined agent results for CallID:', callid);
return [{ json: combinedOutput }];

const llmInputItem = $input.first();
let output = {};
let llmError = null;
let callid = 'unknown';
try {
  callid = llmInputItem.json.callid || $('Prepare S3 Download').item.json.callid || 'unknown';
} catch (error) {
  console.log('CallID not found:', error.message);
}
if (llmInputItem.json.error) {
  llmError = llmInputItem.json.error.message || 'LLM chain error';
  output = { error: llmError, sentiment: null, topic: null, significant_term: null, general_value: null, general_experience: null, sale_outcome: null };
} else if (llmInputItem.json.text) {
  let responseText = llmInputItem.json.text;
  if (responseText.startsWith('```json')) {
    responseText = responseText.slice(7, -3).trim();
  } else if (responseText.startsWith('```')) {
    responseText = responseText.slice(3, -3).trim();
  }
  try {
    output = JSON.parse(responseText);
    for (const key in output) {
      if (output[key] === "unknown") output[key] = null;
    }
    if (output.error === null) delete output.error;
  } catch (error) {
    llmError = 'JSON parse error: ' + error.message;
    output = { error: llmError, raw_text: responseText, sentiment: null, topic: null, significant_term: null, general_value: null, general_experience: null, sale_outcome: null };
  }
} else {
  llmError = 'LLM output empty';
  output = { error: llmError };
}
output.callid = callid;
console.log('Format LLM Response - CallID:', callid);
return [{ json: output }];

const input = $input.first().json;
const callid = input.callid || 'unknown';
const status = input.error ? 'error' : 'success';
console.log(`${status === 'success' ? '✅' : '⚠️'} Call ${callid} processed: ${status}`);
return [{ json: { callid, status, message: status === 'success' ? 'Processed' : 'Error' } }];
